import numpy as np
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import FunctionTransformer, StandardScaler
from sklearn.neural_network import MLPRegressor
from sklearn.compose import TransformedTargetRegressor

def asinh_feat(X):
    return np.arcsinh(np.asarray(X, dtype=float) / 0.003)

def build_model(params, task, seed):
    s = int(seed) if seed is not None else 0
    mlp = MLPRegressor(hidden_layer_sizes=(256, 256), alpha=1e-5, learning_rate_init=1e-3, max_iter=300, early_stopping=True, n_iter_no_change=20, random_state=s)
    pipe = make_pipeline(FunctionTransformer(asinh_feat), StandardScaler(), mlp)
    return TransformedTargetRegressor(regressor=pipe, func=np.log, inverse_func=np.exp, check_inverse=False)
